import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import path from "node:path";

import { describe, expect, it } from "vitest";

const GENERATED_FILES = [
  "tokens.generated.css",
  "tokens.generated.ts",
  "tokens.tailwind.generated.css",
];

/** Splits a generated file into its two header lines and the hashed body. */
function readGenerated(file: string) {
  const text = readFileSync(path.join(__dirname, file), "utf8");
  const firstEnd = text.indexOf("\n");
  const secondEnd = text.indexOf("\n", firstEnd + 1);
  return {
    banner: text.slice(0, firstEnd),
    hashLine: text.slice(firstEnd + 1, secondEnd),
    body: text.slice(secondEnd + 1),
  };
}

describe("generated token files", () => {
  it.each(GENERATED_FILES)("%s carries the generated banner", (file) => {
    const { banner } = readGenerated(file);
    expect(banner).toContain("GENERATED by design/tokens/generate.mjs from tokens.json. Do not edit.");
  });

  it.each(GENERATED_FILES)("%s body matches its tokens-sha256 header (no hand edits)", (file) => {
    const { hashLine, body } = readGenerated(file);
    const declared = /tokens-sha256: ([0-9a-f]{64})/.exec(hashLine)?.[1];
    expect(declared).toBeDefined();
    const actual = createHash("sha256").update(body, "utf8").digest("hex");
    expect(actual).toBe(declared);
  });
});
